package com.movieticket.show; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; import org.springframework.data.repository.query.Param; public interface SeatRepository extends JpaRepository<Seat,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from Seat s where s.showId=:showId and s.seatNumber=:seatNumber") Optional<Seat> lockSeat(@Param("showId") Long showId,@Param("seatNumber") String seatNumber); List<Seat> findByShowIdOrderBySeatNumber(Long showId); long countByShowId(Long showId); void deleteByShowId(Long showId);}